    @inline(__always)
    private func checkEighthVectorClampingRoundingShiftedRightByFromInt64ConstantA(
        _ value: SIMDInt64.Lane
    ) {
        let mismatches = Mismatches(
            "eighthVectorClampingRoundingShiftedRightByFromInt64 with a repeating \(hex(value))"
        )
        let bitsInputs = Array(0...63)
        mismatches.check(
            SIMDInt64.repeating(value),
            SIMDInt64.Vector(raw: HighwayReference.repeatingI64(value)),
            "repeating"
        )
        for bits in bitsInputs {
            mismatches.check(
                H.eighthVector(clamping: SIMDInt64.repeating(value), roundingShiftedRightBy: bits),
                H.EighthVector(
                    raw: HighwayReference.eighthVectorClampingRoundingShiftedRightByI64ToI8(
                        SIMDInt64.repeating(value).raw,
                        Int32(truncatingIfNeeded: bits)
                    )
                ),
                "bits: \(bits)"
            )
        }
        mismatches.record()
    }

